import{_ as a,o as e,c as i,ag as s}from"./chunks/framework.TQKaXlFR.js";const _=JSON.parse('{"title":"数据库迁移","description":"","frontmatter":{},"headers":[],"relativePath":"reference/database-migrations.md","filePath":"reference/database-migrations.md"}'),d={name:"reference/database-migrations.md"};function r(l,t,o,n,h,c){return e(),i("div",null,[...t[0]||(t[0]=[s(`<h1 id="数据库迁移" tabindex="-1">数据库迁移 <a class="header-anchor" href="#数据库迁移" aria-label="Permalink to &quot;数据库迁移&quot;">​</a></h1><p>本页面向部署者和数据库维护人员，用于空库初始化、存量库升级与迁移失败恢复。前提是确认数据库归属、代码版本与备份方案；本页不授权清理现有业务库。</p><h2 id="配置与目录" tabindex="-1">配置与目录 <a class="header-anchor" href="#配置与目录" aria-label="Permalink to &quot;配置与目录&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>当前行为</th></tr></thead><tbody><tr><td>数据库建立</td><td>部署者先创建 schema，Flyway 不创建数据库</td></tr><tr><td>主连接</td><td><code>DB_URL/DB_USERNAME/DB_PASSWORD</code> 同时供 Flyway 和 dynamic-datasource 主库</td></tr><tr><td>默认 location</td><td><code>classpath:db/migration</code></td></tr><tr><td>历史 optional location</td><td><code>classpath:db/optional-migration</code>，仅在环境需要时显式保留</td></tr><tr><td>baseline</td><td><code>baseline-on-migrate=false</code>，<code>baseline-version=2</code> 仅为经评估的历史基线预留</td></tr><tr><td>校验与顺序</td><td>validate-on-migrate=true，out-of-order=false，严格 missing 校验</td></tr><tr><td>清理</td><td>clean-disabled=true；不用 clean/删 history 解决故障</td></tr></tbody></table><p><code>sql/xinghui_admin.sql</code> 是历史导出，不能作为当前初始化方式。旧文档写的 DB_HOST/DB_NAME 自动拼接、默认自动 baseline 已过期。</p><p>Flyway在application.yml显式配置url/user/password，使用独立迁移连接；业务查询走Druid连接池。独立验证脚本应复现这两条装配路径，不能把带默认Wall的业务池交给Flyway后据此判断历史PREPARE迁移失效，也不应为运行查询放宽Wall。</p><h2 id="版本与-repeatable" tabindex="-1">版本与 repeatable <a class="header-anchor" href="#版本与-repeatable" aria-label="Permalink to &quot;版本与 repeatable&quot;">​</a></h2><p>工作区改造前的配对后端目录有 <strong>27个versioned SQL</strong>，从V1/V2到 <code>V20261016_220__ai_attempt_trace.sql</code>；v1.2.0静态旧快照的教程基线为22个、截止V170。版本按Flyway数值段比较，不以字符串排序或文件修改时间判断先后。新增脚本前核对当前分支所有版本，不能复用已存在的版本号。</p><table tabindex="0"><thead><tr><th>迁移阶段</th><th>作用</th></tr></thead><tbody><tr><td>V1 / V2</td><td>基础表与种子；包括公开初始化账号，部署后立即处理</td></tr><tr><td>20260726 系列</td><td>文件权限、旧结构对齐、字符集/排序规则</td></tr><tr><td>20260926 系列</td><td>参数运行态、字典、受控调度、通知、AI模型/场景、微信授权</td></tr><tr><td>20261012.120–160</td><td>内容权限、历史网站管理建立与退役、菜单清理、加密业务配置、低代码</td></tr><tr><td>20261013.170</td><td>旧基线三个一级组、叶子归并与权限关联迁移</td></tr><tr><td>20261016.180</td><td><code>V20261016_180__ai_config_v04.sql</code>：独立AI管理导航、配置/不可变版本、多模型/Key与测试准入</td></tr><tr><td>20261016.190</td><td><code>V20261016_190__ai_template_data_v04.sql</code>：模板、资源、版本与测试/审批证据</td></tr><tr><td>20261016.200</td><td><code>V20261016_200__ai_app_runtime_v04.sql</code>：应用发布版本、业务请求、尝试与阶段日志</td></tr><tr><td>20261016.210</td><td><code>V20261016_210__ai_access_actions.sql</code>：补齐模板/数据动作及AI平台日志审计权限</td></tr><tr><td>20261016.220</td><td><code>V20261016_220__ai_attempt_trace.sql</code>：尝试历史追加实际provider/model/Key版本、供应商追踪ID与输出上限，旧未知值保留NULL</td></tr></tbody></table><p>V130 曾建立网站内容表；V140 已退役这些表/菜单。应保留历史版本链，不删除旧脚本来假装模块从未存在。optional 下同名 R 脚本用于历史资料示例清理，不再创建示例表。曾使用该 location 的库，后续必须保留，才能校验已应用 repeatable 历史。</p><p>旧教程基线曾启用两个location，实测history=23（22 versioned + 清理R），属于历史记录。工作区改造前的一期配对默认新库为27个versioned脚本；启用该optional清理R时通常为28条history。后续工作区与实用改造还会追加脚本，不能把27当作当前目标总数。判断依据是每条script/version/type/checksum/success与实际部署源码及location一致。</p><h2 id="场景工作区增量" tabindex="-1">场景工作区增量 <a class="header-anchor" href="#场景工作区增量" aria-label="Permalink to &quot;场景工作区增量&quot;">​</a></h2><p>直接保存改造新增 <code>V20261016_225__direct_scene_runtime.sql</code>，位于既有V220之后，增加场景身份、不可变配置版本、mutation幂等及请求的场景关联，保留旧应用和请求。已发布版本建立精确兼容映射；未发布草稿不变成可运行配置，歧义关联明确标记。正常空库迁移与旧快照升级已独立验证，应继续以实际部署源码目录和逐条history核对。数据对象接缝复用既有表，本次没有额外V226。</p><p><code>V20261016_227__restore_ai_request_list_action.sql</code> 在V225后恢复独立日志列表F动作，只向原旧日志页实际授权且有效的角色迁移，防止菜单改名丢失原读取权限。配置或场景动作不作为日志授权来源。升级后正常退出重新登录，刷新旧会话的权限快照。</p><p>不要混入后续阶段的未发布迁移或改写旧成功脚本。包含V225/V227的一期工作区配对共29个versioned脚本；optional历史按实际location另核对。</p><h2 id="对话、多-key-与独立配置页增量" tabindex="-1">对话、多 Key 与独立配置页增量 <a class="header-anchor" href="#对话、多-key-与独立配置页增量" aria-label="Permalink to &quot;对话、多 Key 与独立配置页增量&quot;">​</a></h2><p>本轮配置、数据预览、引用保存和对话阅读已原生验证，真实供应商限制见<a href="./../releases/versions.html">版本组合</a>。升级仍须配套对应前后端源码，不能只替换页面。以下脚本位于默认<code>db/migration</code>：</p><table tabindex="0"><thead><tr><th>迁移</th><th>作用与核对点</th></tr></thead><tbody><tr><td><code>V20261018_240__conversation_history.sql</code></td><td>持久化对话/消息与设置测试意图，并保留完整2048字符业务引用，不截断复合主键记录上下文</td></tr><tr><td><code>V20261018_242__ai_database_read_action.sql</code></td><td>增加独立ai:data:database:read动作；初始授权仅实际有效的平台管理员，不把场景编辑或旧资源批准转换为全库读取权</td></tr><tr><td><code>V20261018_243__settings_key_rotation_receipt.sql</code></td><td>增加Key更换的内部执行维护回执，不存明文凭据</td></tr><tr><td><code>V20261018_244__restore_standalone_ai_configuration.sql</code></td><td>恢复独立AI配置二级菜单与原组件，保留原页面/动作关联和操作者停用状态，不增加角色API或数据授权</td></tr><tr><td><code>V20261018_245__ai_key_health.sql</code></td><td>按不可变Key版本记录失效隔离状态，并保存设置mutation的主体范围与带密钥指纹；不存提交正文或Key</td></tr><tr><td><code>V20261018_247__sql_assistance_safe_results.sql</code></td><td>查询助手请求、安全状态与已校验SQL；不持久化隐藏系统提示词、原始供应商输出或查询结果</td></tr><tr><td><code>V20261018_248__business_model_hub.sql</code></td><td>独立业务模型、主体内mutation幂等及每请求冻结的具体调用策略；不改写旧场景Key限制</td></tr><tr><td><code>V20261018_249__ai_channel_catalog_receipts.sql</code></td><td>扫描元数据票据与渠道Key绑定，保存来源/时间和凭据HMAC，不复制Key或密文；未挂票据按时清理</td></tr></tbody></table><p>数据绑定和模型扫描不另建业务表或凭据库；本轮没有V241或V246脚本需求，不手工补号。按实际目标分支逐条核对迁移，不以历史总数或某个文件存在代替迁移成功。Key密文仍依赖原CONFIG_MASTER_KEY，升级时必须保留该值；隔离Key应通过修复与正常连接测试恢复，不直接删状态来绕过验证。</p><h2 id="空库启动" tabindex="-1">空库启动 <a class="header-anchor" href="#空库启动" aria-label="Permalink to &quot;空库启动&quot;">​</a></h2><ol><li>建立专属 utf8mb4/general_ci schema 和账号，确保表数为0。</li><li>设置完整 <code>DB_URL</code> 及账号；检查自己连接的 schema。</li><li>保持 baseline 默认 false，启动当前后端。</li><li>查看 V1/V2 及后续迁移日志，查询完整 history。</li><li>重新启动，确认严格校验成功且原有业务数据保留。</li></ol><div class="language-sql vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SELECT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> DATABASE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(), </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">CURRENT_USER</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(), </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">VERSION</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">();</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SELECT</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> COUNT</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">*</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">AS</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> table_count</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">FROM</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> information_schema</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">tables</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> WHERE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> table_schema</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=DATABASE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">();</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SELECT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> version</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, script, </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">type</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">checksum</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, success</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">FROM</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> flyway_schema_history </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">ORDER BY</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> installed_rank;</span></span></code></pre></div><p>其中表数检查是在首次启动前进行；已有 history 后不能把该步骤转成删表命令。应用代码还依赖 Redis/JWT，不能只凭数据库迁移成功断言整个应用启动验证完成。</p><h2 id="存量库与基线" tabindex="-1">存量库与基线 <a class="header-anchor" href="#存量库与基线" aria-label="Permalink to &quot;存量库与基线&quot;">​</a></h2><p>有业务表但没有 history 的库不会默认自动接受 V2 baseline。先对比其结构、种子、租户数据、当前脚本及依赖版本；规划人工基线或前向迁移，经负责人确认、备份/恢复演练和窗口准备后实施。</p><p>baseline=2 表示将 V1/V2 视为已有，并非自动补齐这两份 SQL 的所有内容。旧结构不一致时，盲目启用 baseline 会留下缺表/字段/权限。不要通过全局设置 <code>baseline-on-migrate=true</code> 把未知库连接问题吞掉。具体升级流程见<a href="./../releases/upgrade.html">升级</a>。</p><h2 id="增加与修复迁移" tabindex="-1">增加与修复迁移 <a class="header-anchor" href="#增加与修复迁移" aria-label="Permalink to &quot;增加与修复迁移&quot;">​</a></h2><p>成功执行过的 versioned SQL 不再修改；修复用更高版本的新脚本。采用具名列、显式字符集/排序规则，评估旧数据和权限关联。MySQL DDL 可能自动提交，失败不能假定整份脚本自动回滚。</p><p>迁移失败时停止反复启动，保留目标 commit、history 和错误短摘要，检查实际 DDL/DML 已完成部分。checksum mismatch、missing migration 与 SQL 执行失败不同，不能一律执行 <code>repair</code>。只有经审查确认 schema 与历史一致的方案才考虑 repair；它不会替你修复业务结构。</p><p>不得随意删库、清表、删除 <code>flyway_schema_history</code> 或将 out-of-order/ignore-migration-patterns 改宽来得到绿灯。需要回退时按<a href="./../operations/backup-restore.html">备份恢复</a>成套恢复 DB、主密钥、对象与配套代码。</p><h2 id="已验证与源码依据" tabindex="-1">已验证与源码依据 <a class="header-anchor" href="#已验证与源码依据" aria-label="Permalink to &quot;已验证与源码依据&quot;">​</a></h2><p>旧教程基线曾在隔离MySQL8.0.12空库完成含V170的23条history、重启strict validate及真实服务验证。当前配对源码的正式CI已通过MySQL5.7与8.0两组服务矩阵，覆盖空库迁移、严格校验和认证服务检查，并包含AI配置经Druid Wall的HTTP回归。当前一期另有真实记录摘要组合验收；这些结果不等于独立机器或读者目标库的升级演练，不授权修改已应用迁移。</p><p>源码：后端 <code>system-admin/src/main/resources/application.yml</code>、<code>application-datasource.yml</code>、<code>db/migration/*.sql</code>、<code>db/optional-migration/*.sql</code>、<code>system-admin/src/test/java/com/xinghuiTec/quality/ReleaseServicesIT.java</code>及 <code>.github/workflows/ci.yml</code> 的MySQL服务矩阵；版本组合见<a href="./../releases/versions.html">版本页</a>。</p>`,33)])])}const k=a(d,[["render",r]]);export{_ as __pageData,k as default};
